// Virtual Memory Components (32-bit, 4KB Pages)
#define PAGE_SHIFT 12
#define PAGE_SIZE (1 << PAGE_SHIFT) // 4096 bytes

// Page Table Entry (PTE) Structure: The Mapping Data
typedef struct {
    unsigned int Valid : 1;     // Is page currently cached in RAM?
    unsigned int Writable : 1;  // Protection bit
    unsigned int Accessed : 1;  // Replacement Policy Hint (Caching feedback)
    unsigned int Dirty : 1;     // Needs to be written back to disk
    unsigned int PFN : 20;      // Physical Frame Number (Address Abstraction)
} PTE;

// Per-Process Page Table Base Pointer
PTE* Current_PageTable;

// Virtual Address (VA) Decomposition
// VA = [VPN (Index into PT) | Offset (Index within Page)]
#define VPN(va) ((va) >> PAGE_SHIFT)
#define Offset(va) ((va) & (PAGE_SIZE - 1))

// Hardware Cache: Translation Lookaside Buffer (TLB)
// Stores recently used PTEs for fast mapping (reducing latency)
// If TLB Miss, hardware performs Page Table Walk (slow)
// If PTE Valid=0, OS handles Page Fault (cache miss to disk)
